bool FindProcessorWithSoonestRelease()
{
    int best_len = BufferSize +1;
    bool first_candidate = true;
    bool ret = false;
    t_id best_running;
    int i;

    soonest_release = MaxTime + 1;

    // check what is the next task to be released to allocate
    // the current task over analysis
    for (i = 0; i < Procs-1; i++)
    {
        r_id r = task[gid][tid].resources[i];
        t_id running = buffer[r].element[0];

        if (buffer[r].length < best_len)
        {
            if (first_candidate ||
                time[gid][running] > time[gid][best_running])
            {
                best_len = buffer[r].length;
                UpdateTaskResourceInfo(gid, tid, r);
                best_running = running;
                ret = true;
                first_candidate = false;
            }
        }
    }

    return ret;
}


void FindPredecessors(int task_resource, bool in_same_resource)
{
    int i;

    predecessors.size = 0;

    for (i = 0; i < Tasks; i++)
    {
        if (cons[gid][i][tid] > 0 && task[gid][i].type == 0)
        {
            int pred_res = task[gid][i].curr_resource;
            int this_res = task_resource;

            if (this_res != -1 &&
                pred_res != -1 &&
                (in_same_resource ? (this_res == pred_res) : (this_res != pred_res)))
            {
                // buffer[resource()].element[0] == tid? 1 : 0
                predecessors.list[predecessors.size].first = gid;
                predecessors.list[predecessors.size].second = i;
                predecessors.size++;
            }
        }
    }
}

void FindEdgesFromPredecessors()
{
    int i;

    predecessors_egdes.size = 0;

    for (i = 0; i < predecessors.size; i++)
    {
        int pred = predecessors.list[i].second;
        int edge_id = FindEdge(pred, tid);
        if (edge_id >= 0)
        {
            pair_t edge = {gid, edge_id};
            predecessors_egdes.list[predecessors_egdes.size] = edge;
            predecessors_egdes.size++;
        }
    }
}

int FindBestProcessor()
{
    int best_len = Tasks +1;
    int result = -1;
    int i;

     for (i = 0; i < Procs-1; i++)
    {
        r_id r = task[gid][tid].resources[i];

        if (buffer[r].length < best_len &&
            task[gid][tid].curr_resource == -1 &&
            load[r] + task[gid][tid].wcet <= load_limit[r])
        {
            best_len = buffer[r].length;
            result = r;
        }
    }

    return result;
}

void SearchIdleResouce()
{
    // find best resource for the task
    resource_id = FindBestProcessor();
    if (resource_id >= 0)
        UpdateTaskResourceInfo(gid, tid, resource_id);
}

void insert_task_in_buffer() {
  d_id d = param.dag;
  t_id t = param.task;
  r_id r = param.resource;
  int place = (param.preempt ? 0 : 1);

  // Find out where to put the task
  while ( place < buffer[r].length && task[d][buffer[r].element[place]].pri >= task[d][t].pri ) {
    place++;
  }
  insert_at(place,t,r);
}

int[0,Tasks] place;
t_id tid;
r_id rid;
bool preempt;

void readParameters() {
  tid = param.task; rid = param.resource; preempt = param.preempt;
}

void resetVars() {
  place = tid = rid = 0;
}

